/* ------------------------------------------------------------------ local drawing helpers (plain divs, palette aware) */

const X0 = 180;
const X1 = 1740;
const r3 = (n: number) => String(Math.round(n * 1000) / 1000);

type Span = {from: number; to: number; color: string; row?: number; label?: string; outside?: boolean; o?: number; g?: number};
type Mark = {at: number; color?: string; label?: string; h?: number; side?: 'top' | 'bottom'; dashed?: boolean; o?: number; off?: number};
type Band = {from: number; to: number; color: string; label?: string; o?: number};

/** A timeline: an axis with keyframe diamonds, spans (rows above the axis), vertical marks and an optional highlighted band. */
const Track: React.FC<{
  y: number; max: number; min?: number; x0?: number; x1?: number; title?: string; titleColor?: string; ticks?: number[]; tickFmt?: (v: number) => string;
  kf?: number[]; kfLabel?: (v: number) => string; kfColor?: string; spans?: Span[]; marks?: Mark[]; band?: Band; rows?: number; o?: number;
}> = ({y, max, min = 0, x0 = X0, x1 = X1, title, titleColor, ticks = [], tickFmt = (v) => String(v), kf = [], kfLabel = (v) => String(v), kfColor, spans = [], marks = [], band, rows, o = 1}) => {
  const x = (v: number) => x0 + ((v - min) / (max - min)) * (x1 - x0);
  const nRows = rows ?? Math.max(1, ...spans.map((s) => (s.row ?? 0) + 1));
  const kc = kfColor ?? C.cyan;
  return (
    <div style={{position: 'absolute', left: 0, top: 0, width: W, height: 0, opacity: o, fontFamily: F.mono}}>
      {title && <div style={{position: 'absolute', left: x0, top: y - 56 * nRows - 62, fontFamily: F.sans, fontSize: 28, fontWeight: 600, letterSpacing: 1, color: titleColor ?? C.dim, whiteSpace: 'nowrap'}}>{title}</div>}
      {band && (
        <div style={{position: 'absolute', left: x(band.from), top: y - 56 * nRows - 8, width: x(band.to) - x(band.from), height: 56 * nRows + 30, opacity: band.o ?? 1, background: `${band.color}22`, border: `2px dashed ${band.color}`, borderRadius: 10, boxSizing: 'border-box'}}>
          {band.label && <div style={{position: 'absolute', left: 0, top: -36, width: '100%', textAlign: 'center', fontFamily: F.sans, fontSize: 24, fontWeight: 700, color: band.color, whiteSpace: 'nowrap'}}>{band.label}</div>}
        </div>
      )}
      <div style={{position: 'absolute', left: x0, top: y, width: x1 - x0, height: 4, background: C.mute, borderRadius: 2}} />
      {ticks.filter((v) => !kf.includes(v)).map((v) => (
        <React.Fragment key={`t${v}`}>
          <div style={{position: 'absolute', left: x(v) - 1, top: y, width: 2, height: 14, background: C.mute}} />
          <div style={{position: 'absolute', left: x(v) - 70, top: y + 18, width: 140, textAlign: 'center', fontSize: 22, color: C.dim, whiteSpace: 'nowrap'}}>{tickFmt(v)}</div>
        </React.Fragment>
      ))}
      {spans.map((s, i) => {
        const wpx = Math.max(6, (x(s.to) - x(s.from)) * (s.g ?? 1));
        const top = y - 56 * ((s.row ?? 0) + 1);
        return (
          <div key={`s${i}`} style={{position: 'absolute', left: x(s.from), top, width: wpx, height: 44, opacity: s.o ?? 1, boxSizing: 'border-box', borderRadius: 8, background: `${s.color}40`, border: `3px solid ${s.color}`, display: 'flex', alignItems: 'center', justifyContent: 'center', color: C.text, fontSize: 22, fontWeight: 700, whiteSpace: 'nowrap'}}>
            {!s.outside && s.label}
            {s.outside && s.label && <span style={{position: 'absolute', left: wpx + 12, color: s.color, fontFamily: F.sans, fontSize: 24, fontWeight: 700}}>{s.label}</span>}
          </div>
        );
      })}
      {marks.map((m, i) => {
        const h = m.h ?? 56 * nRows + 18;
        const top = m.side === 'bottom';
        return (
          <React.Fragment key={`m${i}`}>
            <div style={{position: 'absolute', left: x(m.at) - 1.5, top: top ? y + (m.off ?? 0) : y - h, width: 0, height: top ? h + 14 : h + 14, borderLeft: `3px ${m.dashed === false ? 'solid' : 'dashed'} ${m.color ?? C.red}`, opacity: m.o ?? 1}} />
            {m.label && <div style={{position: 'absolute', left: x(m.at) - 200, top: top ? y + (m.off ?? 0) + h + 22 : y - h - 40, width: 400, textAlign: 'center', fontFamily: F.sans, fontSize: 24, fontWeight: 700, color: m.color ?? C.red, whiteSpace: 'nowrap', opacity: m.o ?? 1}}>{m.label}</div>}
          </React.Fragment>
        );
      })}
      {kf.map((v) => (
        <React.Fragment key={`k${v}`}>
          <div style={{position: 'absolute', left: x(v) - 11, top: y - 9, width: 22, height: 22, background: kc, transform: 'rotate(45deg)', borderRadius: 3, border: `3px solid ${C.bg}`, boxSizing: 'border-box'}} />
          {kfLabel(v) !== '' && <div style={{position: 'absolute', left: x(v) - 70, top: y + 20, width: 140, textAlign: 'center', fontSize: 22, fontWeight: 700, color: kc, whiteSpace: 'nowrap'}}>{kfLabel(v)}</div>}
        </React.Fragment>
      ))}
    </div>
  );
};

type BarRow = {label: string; parts: {v: number; color: string; label?: string; o?: number}[]; text?: string; o?: number};
/** Horizontal bars with one or more stacked parts, scaled to `max`. */
const Bars: React.FC<{y: number; rows: BarRow[]; max: number; rowH?: number; x0?: number; wmax?: number; p?: number}> = ({y, rows, max, rowH = 92, x0 = 520, wmax = 1000, p = 1}) => (
  <>
    {rows.map((r, i) => {
      let acc = 0;
      return (
        <div key={i} style={{position: 'absolute', left: 0, top: y + i * rowH, width: W, height: rowH, opacity: r.o ?? 1, fontFamily: F.sans}}>
          <div style={{position: 'absolute', left: 90, top: 0, width: x0 - 120, height: 68, display: 'flex', alignItems: 'center', justifyContent: 'flex-end', textAlign: 'right', fontSize: 30, fontWeight: 600, color: C.dim, lineHeight: 1.1}}>{r.label}</div>
          {r.parts.map((pt, k) => {
            const left = x0 + (acc / max) * wmax;
            const w = Math.max(8, (pt.v / max) * wmax * p);
            acc += pt.v;
            return (
              <div key={k} style={{position: 'absolute', left, top: 0, width: w, height: 68, boxSizing: 'border-box', background: pt.color, border: `3px solid ${C.bg}`, borderRadius: 8, display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: F.mono, fontSize: 24, fontWeight: 700, color: C.bg, whiteSpace: 'nowrap', opacity: pt.o ?? 1, boxShadow: D.glow ? 'none' : `4px 4px 0 ${pt.color}55`}}>{p > 0.85 ? pt.label : ''}</div>
            );
          })}
          {r.text && <div style={{position: 'absolute', left: x0 + (acc / max) * wmax * p + 20, top: 0, height: 68, display: 'flex', alignItems: 'center', fontFamily: F.display, fontSize: 52 * D.k, fontWeight: 800, color: C.text, whiteSpace: 'nowrap', opacity: p > 0.85 ? 1 : 0}}>{r.text}</div>}
        </div>
      );
    })}
  </>
);

