/* 9. who places keyframes */
const Gop: React.FC<SceneProps> = ({t}) => {
  const k = E.gop.g100 as number[];
  return (
    <>
      <Head over="Who places keyframes" title="-g 100 is only a maximum." o={ep(t, 0.2, 0.8)} />
      <Cmd y={290} text={E.cmd.g100} hi="-g 100" size={30} color={C.cyan} o={ep(t, 0.8, 1.4)} />
      <Track y={520} max={E.gop.seconds} ticks={[0, 2, 4, 6, 8, 10]} tickFmt={(v) => `${v} s`} kf={k} kfLabel={(v) => `${v}`} kfColor={C.cyan} title="keyframes the encoder chose" rows={1} o={ep(t, 1.6, 2.2)}
        spans={k.map((v, i) => ({from: v, to: k[i + 1] ?? E.gop.seconds, color: C.cyan, row: 0, label: `${r3((k[i + 1] ?? E.gop.seconds) - v)} s`, o: ep(t, 4.6 + i * 0.5, 5.2 + i * 0.5)}))}
        marks={(E.gop.cuts as number[]).map((c) => ({at: c, color: C.red, label: `scene cut ${c}`, side: 'bottom' as const, off: 48, h: 22, o: ep(t, 3.0, 3.8)}))} />
      <Mid y={760} size={34} color={C.dim} o={ep(t, 7.4, 8.2)}>The encoder adds a keyframe on every hard cut, on top of the maximum.</Mid>
    </>
  );
};

/* 10. grid or placed */
const Grid: React.FC<SceneProps> = ({t}) => {
  const cutsOf = (named: boolean) => (E.gop.cuts as number[]).map((c, i) => ({at: c, color: C.red, h: 62, label: named && i === 0 ? 'scene cut' : undefined, o: ep(t, 0.8, 1.4) * 0.8}));
  const row = (y: number, title: string, kf: number[], col: string, a: number, named = false) => (
    <Track y={y} max={E.gop.seconds} ticks={[0, 2, 4, 6, 8, 10]} tickFmt={(v) => `${v} s`} kf={kf} kfLabel={(v) => `${v}`} kfColor={col} title={title} titleColor={col} rows={1} marks={cutsOf(named)} o={ep(t, a, a + 0.7)} />
  );
  return (
    <>
      <Head over="A grid, or placed" title="Three ways to place them." o={ep(t, 0.2, 0.8)} />
      {row(420, '-sc_threshold 0 · a strict grid', E.gop.nosc, C.amber, 1.2, true)}
      {row(610, '-force_key_frames 3.2,6.8 · exactly there', E.gop.forced, C.green, 3.4)}
      {row(800, '-force_key_frames 2 · added to the cuts', E.gop.force2, C.cyan, 5.6)}
    </>
  );
};

