    <Track y={510} max={E.rec.frames} kf={E.rec.prepared} kfLabel={(v) => String(v)} ticks={[]} title="keyframes of the prepared clip" rows={1} o={ep(t, 1.4, 2.0)}
      spans={[{from: E.rec.startFrame, to: E.rec.lastFrame + 1, color: C.green, row: 0, label: `${E.rec.wantFrames}`, o: ep(t, 2.4, 3.0)}]} />
