/* 17. cheat sheet */
const Sheet: React.FC<SceneProps> = ({t}) => {
  const card = (x: number, y: number, label: string, cmd: string, sub: string, color: string, a: number) => (
    <Panel x={x} y={y} w={880} h={250} color={color} o={ep(t, a, a + 0.7)}>
      <Label color={color}>{label}</Label>
      <div style={{fontFamily: F.mono, fontSize: 21, color: C.text, margin: '14px 0 10px', whiteSpace: 'nowrap', background: C.codeBg, padding: '10px 14px', borderRadius: 10}}>{cmd}</div>
      <div style={{fontSize: 28, color: C.dim, fontFamily: F.sans}}>{sub}</div>
    </Panel>
  );
  return (
    <>
      <Head over="Cheat sheet" title="Which command to trust." o={ep(t, 0.2, 0.8)} />
      {card(60, 290, 'Exact cut', E.cmd.reencode, `${E.rec.enc.frames} frames, both readers agree`, C.green, 1.0)}
      {card(980, 290, 'Instant cut', E.cmd.copyPrepared, `needs keyframes at the cut: ${E.rec.prep.frames} frames, ${E.rec.prep.packets} packets`, C.cyan, 2.4)}
      {card(60, 570, 'From the end', E.cmd.sseofEnc, `${E.sseof.enc.frames} frames; copy gave ${E.sseof.copy.frames}`, C.amber, 3.8)}
      {card(980, 570, 'The tail', E.cmd.shortestCopy, `copy: ${E.short.copyFrames} of ${E.short.srcFrames} frames. Count them.`, C.red, 5.2)}
    </>
  );
};

